def shortest_path(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[rows-1][cols-1] == 1:
        return -1

    queue = deque()
    queue.append((0, 0))
    visited = set()
    visited.add((0, 0))
    distance = {(0, 0): 0}

    while queue:
        r, c = queue.popleft()
        if r == rows - 1 and c == cols - 1:
            return distance[(r, c)]
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
